import base64
import os

icons = {
  "16": "",
  "48": "",
  "128": ""
}

os_dirs = ['public/icons', 'dist/icons', 'icons']
for d in os_dirs:
    if not os.path.exists(d):
        os.makedirs(d)

for size, data in icons.items():
    binary_data = base64.b64decode(data)
    for d in os_dirs:
        with open(os.path.join(d, f"icon{size}.png"), "wb") as f:
            f.write(binary_data)

print("Icons updated successfully.")
